        let orig: Arc<T> = Arc::new(value);
        let inner: AuxInner = orig.clone();
        let outer = Box::new(inner);
        let raw: *mut AuxInner = Box::into_raw(outer);
                raw as *mut _,
                Some(free_boxed_value::<AuxInner>),
        Ok(orig)
    }

