        let ascii = |nibble| nibble + if nibble < 10 { b'0' } else { letter };
        for (&byte, pair) in src.iter().zip(dst.chunks_exact_mut(2)) {
            pair[0].write(ascii(byte >> 4));
            pair[1].write(ascii(byte & 15));
